import{_ as e,c as d,o,a3 as c}from"./chunks/framework.czLORLkK.js";const y=JSON.parse('{"title":"SyncAPIM WAF 위협 탐지, 스펙 드리프트 감사 및 PII 마스킹 거버넌스","description":"SyncAPIM의 미등록 섀도우 API 자동 발견, OpenAPI 3.0.1 Contract Drift 비교 감사, 6대 웹·API 공격 탐지 룰 및 8대 민감정보 실시간 마스킹 체계를 설명합니다.","frontmatter":{"title":"SyncAPIM WAF 위협 탐지, 스펙 드리프트 감사 및 PII 마스킹 거버넌스","sidebarTitle":"WAF 위협 탐지 & PII 마스킹","description":"SyncAPIM의 미등록 섀도우 API 자동 발견, OpenAPI 3.0.1 Contract Drift 비교 감사, 6대 웹·API 공격 탐지 룰 및 8대 민감정보 실시간 마스킹 체계를 설명합니다.","head":[["meta",{"name":"keywords","content":"SyncAPIM WAF, 섀도우 API, OpenAPI Contract Drift, SQL Injection, XSS, SSRF, RCE, JWT 검증, 개인정보 마스킹"}],["meta",{"property":"og:title","content":"SyncAPIM WAF 위협 탐지, 스펙 드리프트 감사 및 PII 마스킹 거버넌스"}],["meta",{"property":"og:description","content":"실시간 트래픽 기반 OpenAPI 3.0.1 명세 자동 추론, Contract Drift 감사 및 6대 공격·8대 민감정보 보호 체계"}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/syncapim/waf-and-pii-governance"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/syncapim/waf-and-pii-governance"}]],"sort":3},"headers":[],"relativePath":"syncapim/waf-and-pii-governance.md","filePath":"ko/syncapim/waf-and-pii-governance.md","lastUpdated":1794045358000}'),l={name:"syncapim/waf-and-pii-governance.md"};function a(i,t,n,s,r,p){return o(),d("div",null,[...t[0]||(t[0]=[c('<h1 id="syncapim-waf-위협-탐지-스펙-드리프트-감사-및-pii-마스킹-거버넌스" tabindex="-1">SyncAPIM WAF 위협 탐지, 스펙 드리프트 감사 및 PII 마스킹 거버넌스 <a class="header-anchor" href="#syncapim-waf-위협-탐지-스펙-드리프트-감사-및-pii-마스킹-거버넌스" aria-label="Permalink to “SyncAPIM WAF 위협 탐지, 스펙 드리프트 감사 및 PII 마스킹 거버넌스”">​</a></h1><p><code>SyncAPIM</code>은 단순 시그니처 방화벽을 넘어 <strong>API 인벤토리 가시성 확보(Shadow API Discovery)</strong>, <strong>설계 명세 대비 실트래픽 정합성 검증(Contract Drift Audit)</strong>, <strong>실시간 웹·API 공격 차단(WAF)</strong>, <strong>개인·금융 민감정보 유출 방지(PII Masking)</strong>의 4단계 보안 거버넌스를 단일 파이프라인으로 제공합니다.</p><hr><h2 id="_1-미등록-섀도우-api-자동-발견-및-openapi-3-0-1-추론" tabindex="-1">1. 미등록 섀도우 API 자동 발견 및 OpenAPI 3.0.1 추론 <a class="header-anchor" href="#_1-미등록-섀도우-api-자동-발견-및-openapi-3-0-1-추론" aria-label="Permalink to “1. 미등록 섀도우 API 자동 발견 및 OpenAPI 3.0.1 추론”">​</a></h2><ol><li><strong>실트래픽 기반 엔드포인트 카탈로그 자동 생성</strong>: <ul><li><code>sync-apim-detector</code>의 <code>DetectionRuleServiceImpl</code>은 수신된 HTTP 패킷의 <code>host</code>, <code>method</code>, <code>path</code> 조합을 분석하여 미등록 엔드포인트를 <code>wapf_api_endpoint</code> 및 <code>wapf_api_endpoint_detail</code>에 자동 등록합니다.</li><li>요청 쿼리스트링, 요청 본문(JSON), 응답 본문(JSON)의 모든 필드를 재귀적으로 파싱하여 <code>wapf_data_field</code>에 데이터 타입과 JSONPath(<code>$.data.accountNo</code> 등)를 기록합니다.</li></ul></li><li><strong>OpenAPI 3.0.1 명세 실시간 합성 및 Contract Drift 비교 감사</strong>: <ul><li>관찰된 입출력 필드를 바탕으로 표준 OpenAPI 3.0.1 JSON 명세(<code>wapf_open_api_spec</code>)를 자동 합성합니다.</li><li><code>POST /api/v1/apim/spec/audit</code> (<code>WapfOpenApiSpecServiceImpl.auditContractDrift</code>) 호출 시 설계 스펙(<code>designSpec</code>)과 실트래픽 스펙을 비교하여 다음 3가지 드리프트를 판별합니다: <ul><li><strong><code>UNDOCUMENTED_RESPONSE_FIELD</code></strong>: 설계 명세에 정의되지 않은 내부 필드나 민감 필드가 실제 API 응답으로 노출된 경우</li><li><strong><code>MISSING_REQUIRED_PARAM</code></strong>: 설계상 필수인 요청 파라미터가 누락된 채 호출되는 경우</li><li><strong><code>SHADOW_ENDPOINT</code></strong>: 승인된 API 명세서에 존재하지 않는 미등록 디버그·레거시 엔드포인트가 호출되는 경우</li></ul></li></ul></li></ol><hr><h2 id="_2-6대-표준-웹·api-위협-탐지-룰-wapf-rule" tabindex="-1">2. 6대 표준 웹·API 위협 탐지 룰 (<code>wapf_rule</code>) <a class="header-anchor" href="#_2-6대-표준-웹·api-위협-탐지-룰-wapf-rule" aria-label="Permalink to “2. 6대 표준 웹·API 위협 탐지 룰 (wapf_rule)”">​</a></h2><p><code>db/04_seed_domain.sql</code>에 기본 탑재된 6대 핵심 위협 탐지 룰은 요청 URL, 헤더, 쿼리, 바디 전체를 대상으로 실시간 정규식 매칭 및 JWT 구조 검증을 수행합니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">룰 ID</th><th style="text-align:left;">위협 탐지 룰 명칭</th><th style="text-align:center;">심각도</th><th style="text-align:left;">주요 탐지 패턴 및 방어 대상</th></tr></thead><tbody><tr><td style="text-align:left;"><code>rule_apim_001</code></td><td style="text-align:left;"><strong>SQL 인젝션 공격 탐지</strong></td><td style="text-align:center;"><code>4</code> (Critical)</td><td style="text-align:left;"><code>UNION SELECT</code>, <code>OR 1=1</code>, <code>DROP TABLE</code>, <code>SLEEP()</code>, <code>WAITFOR DELAY</code> 등 DB 조작 구문</td></tr><tr><td style="text-align:left;"><code>rule_apim_002</code></td><td style="text-align:left;"><strong>크로스 사이트 스크립팅 탐지</strong></td><td style="text-align:center;"><code>3</code> (High)</td><td style="text-align:left;"><code>&lt;script&gt;</code>, <code>javascript:</code>, <code>onerror=</code>, <code>onload=</code> 등 악성 스크립트 삽입</td></tr><tr><td style="text-align:left;"><code>rule_apim_003</code></td><td style="text-align:left;"><strong>서버 사이드 요청 위조 탐지</strong></td><td style="text-align:center;"><code>4</code> (Critical)</td><td style="text-align:left;"><code>169.254.169.254</code>(클라우드 메타데이터), <code>localhost</code>, <code>127.0.0.1</code>, <code>file://</code>, <code>gopher://</code> 내부망 탐색</td></tr><tr><td style="text-align:left;"><code>rule_apim_004</code></td><td style="text-align:left;"><strong>원격 명령어 실행 공격 탐지</strong></td><td style="text-align:center;"><code>4</code> (Critical)</td><td style="text-align:left;"><code>; cat /etc/passwd</code>, <code>| bash</code>, <code>`whoami`</code>, <code>cmd.exe</code>, <code>powershell</code> 등 OS 명령어 주입</td></tr><tr><td style="text-align:left;"><code>rule_apim_005</code></td><td style="text-align:left;"><strong>디렉터리 트래버설 탐지</strong></td><td style="text-align:center;"><code>3</code> (High)</td><td style="text-align:left;"><code>../</code>, <code>..\\\\</code>, <code>/etc/passwd</code>, <code>win.ini</code>, URL 인코딩된 상위 경로 우회 접근</td></tr><tr><td style="text-align:left;"><code>rule_apim_006</code></td><td style="text-align:left;"><strong>JWT 토큰 무결성 및 서명 검증</strong></td><td style="text-align:center;"><code>4</code> (Critical)</td><td style="text-align:left;"><code>alg: &quot;none&quot;</code> 서명 우회 공격, 만료 토큰(<code>exp</code> 도과), 비정상 페이로드 구조 변조</td></tr></tbody></table><hr><h2 id="_3-7대-보안-정책-그룹-wapf-policy-및-실시간-redis-캐시-동기화" tabindex="-1">3. 7대 보안 정책 그룹 (<code>wapf_policy</code>) 및 실시간 Redis 캐시 동기화 <a class="header-anchor" href="#_3-7대-보안-정책-그룹-wapf-policy-및-실시간-redis-캐시-동기화" aria-label="Permalink to “3. 7대 보안 정책 그룹 (wapf_policy) 및 실시간 Redis 캐시 동기화”">​</a></h2><p>관리 콘솔(<code>/waf/policy</code>)에서 보안 정책이나 룰 매핑을 변경하면 <code>WapfPolicyServiceImpl.syncPolicyRuleCache()</code>가 즉시 실행되어 Redis(<code>wapf:policy:rules</code>)를 갱신하며, <code>sync-apim-detector</code>를 재시작하지 않아도 실시간 탐지 파이프라인에 즉시 반영됩니다.</p><ul><li><strong><code>pol_apim_001</code> (인증 보안 정책)</strong>: 기본(<code>basic=true</code>) 글로벌 보호 정책</li><li><strong><code>pol_apim_002</code> (접근 제어 정책)</strong>: 관리자 및 내부 정산 API 접근 통제</li><li><strong><code>pol_apim_003</code> (데이터 암호화 정책)</strong>: 금융·결제 구간 전송 데이터 보호</li><li><strong><code>pol_apim_004</code> (권한 인가 정책)</strong>: BOLA/IDOR 객체 수준 권한 검증</li><li><strong><code>pol_apim_005</code> (네트워크 보안 정책)</strong>: 외부 콜백 및 웹훅 SSRF 방어</li><li><strong><code>pol_apim_006</code> (개인정보 보호 정책)</strong>: 고객 마이데이터 조회 API 집중 감시</li><li><strong><code>pol_apim_007</code> (침입 탐지 정책)</strong>: 고위험 RCE·SQLi 페이로드 즉시 차단</li></ul><hr><h2 id="_4-8대-개인·금융-민감정보-pii-실시간-마스킹-wapf-sensitivity" tabindex="-1">4. 8대 개인·금융 민감정보(PII) 실시간 마스킹 (<code>wapf_sensitivity</code>) <a class="header-anchor" href="#_4-8대-개인·금융-민감정보-pii-실시간-마스킹-wapf-sensitivity" aria-label="Permalink to “4. 8대 개인·금융 민감정보(PII) 실시간 마스킹 (wapf_sensitivity)”">​</a></h2><p>API 요청 및 응답에 포함된 개인정보가 로그나 외부 응답으로 평문 노출되지 않도록 8대 민감정보 정규식을 실시간 스캔하여 마스킹(<code>***</code>) 처리하고, 해당 필드를 <code>wapf_data_field.sensitivity_uuid</code>에 자동 태깅합니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">식별자</th><th style="text-align:left;">민감정보 항목</th><th style="text-align:center;">심각도</th><th style="text-align:left;">탐지 대상 포맷 요약</th></tr></thead><tbody><tr><td style="text-align:left;"><code>sens_apim_001</code></td><td style="text-align:left;"><strong>계좌번호</strong></td><td style="text-align:center;"><code>3</code> (High)</td><td style="text-align:left;">시중은행 계좌번호 포맷 (<code>\\d{3,4}-\\d{2,6}-\\d{4,6}</code>)</td></tr><tr><td style="text-align:left;"><code>sens_apim_002</code></td><td style="text-align:left;"><strong>이메일</strong></td><td style="text-align:center;"><code>2</code> (Medium)</td><td style="text-align:left;">표준 이메일 주소 포맷</td></tr><tr><td style="text-align:left;"><code>sens_apim_003</code></td><td style="text-align:left;"><strong>카드번호</strong></td><td style="text-align:center;"><code>4</code> (Critical)</td><td style="text-align:left;">16자리 신용·체크카드 번호 (<code>\\d{4}-\\d{4}-\\d{4}-\\d{4}</code>)</td></tr><tr><td style="text-align:left;"><code>sens_apim_004</code></td><td style="text-align:left;"><strong>주민등록번호</strong></td><td style="text-align:center;"><code>4</code> (Critical)</td><td style="text-align:left;">13자리 주민등록번호 및 외국인등록번호 (<code>\\d{6}-[1-4]\\d{6}</code>)</td></tr><tr><td style="text-align:left;"><code>sens_apim_005</code></td><td style="text-align:left;"><strong>이름</strong></td><td style="text-align:center;"><code>2</code> (Medium)</td><td style="text-align:left;">JSON 필드 내 성명 식별 패턴</td></tr><tr><td style="text-align:left;"><code>sens_apim_006</code></td><td style="text-align:left;"><strong>비밀번호</strong></td><td style="text-align:center;"><code>4</code> (Critical)</td><td style="text-align:left;"><code>password</code>, <code>passwd</code>, <code>pwd</code>, <code>secret</code> 키-값 평문 노출</td></tr><tr><td style="text-align:left;"><code>sens_apim_007</code></td><td style="text-align:left;"><strong>IP 주소</strong></td><td style="text-align:center;"><code>2</code> (Medium)</td><td style="text-align:left;">내부망 및 클라이언트 IPv4 주소 포맷</td></tr><tr><td style="text-align:left;"><code>sens_apim_008</code></td><td style="text-align:left;"><strong>전화번호</strong></td><td style="text-align:center;"><code>3</code> (High)</td><td style="text-align:left;">휴대전화 및 일반 전화번호 (<code>01[016789]-\\d{3,4}-\\d{4}</code>)</td></tr></tbody></table>',17)])])}const f=e(l,[["render",a]]);export{y as __pageData,f as default};
